  # Defines the Twilio SDK type.
  class Twilio
    attr_reader :accounts, :addresses, :applications, :authorized_connect_apps,
                :available_phone_numbers, :balance, :calls, :conferences, :connect_apps,
                :incoming_phone_numbers, :keys, :messages, :queues, :signing_keys, :notifications,
                :outgoing_caller_ids, :validation_requests, :recordings, :short_codes, :sip, :tokens,
                :transcriptions, :usage_records, :usage_triggers

    SUB_NAMESPACES = {
      accounts: AccountsNamespace,
      addresses: AddressesNamespace,
      applications: ApplicationsNamespace,
      authorized_connect_apps: AuthorizedConnectAppsNamespace,
      available_phone_numbers: AvailablePhoneNumbersNamespace,
      balance: BalanceNamespace,
      calls: CallsNamespace,
      conferences: ConferencesNamespace,
      connect_apps: ConnectAppsNamespace,
      incoming_phone_numbers: IncomingPhoneNumbersNamespace,
      keys: KeysNamespace,
      messages: MessagesNamespace,
      queues: QueuesNamespace,
      signing_keys: SigningKeysNamespace,
      notifications: NotificationsNamespace,
      outgoing_caller_ids: OutgoingCallerIdsNamespace,
      validation_requests: ValidationRequestsNamespace,
      recordings: RecordingsNamespace,
      short_codes: ShortCodesNamespace,
      sip: SipNamespace,
      tokens: TokensNamespace,
      transcriptions: TranscriptionsNamespace,
      usage_records: UsageRecordsNamespace,
      usage_triggers: UsageTriggersNamespace,
    }.freeze
    private_constant :SUB_NAMESPACES

    def initialize(config)
      @config = config
      SUB_NAMESPACES.each do |accessor, namespace|
        instance_variable_set(:"@#{accessor}", namespace.new(config))
      end
    end

    # Turns SDK logging on and configures it. Logging is OFF by default — this
    # SDK reports nothing until you call this (or construct the client with a
    # config whose logging is enabled). Reports go to the endpoint this build was
    # generated with, or to the endpoint you pass; with neither, nothing is sent.
    # Pass enabled: false to turn logging back off.
    def set_logging_config(**fields)
      logging = (@config.logging ||= LoggingConfig.new)
      # Opting in IS the point of this call, so enabled flips to true — the
      # keyword loop below runs after, so an explicit enabled: false wins.
      logging.enabled = true
      fields.each do |key, value|
        setter = :"#{key}="
        raise ArgumentError, "LoggingConfig has no field #{key}" unless logging.respond_to?(setter)

        logging.public_send(setter, value)
      end
      logging
    end

  end
